<template><div class="page"><p>员工账号、角色与权限复用统一权限中心维护。</p><div class="actions"><el-button type="primary" @click="router.push('/system/user')">管理员工账号</el-button><el-button @click="router.push('/system/role')">管理角色权限</el-button><el-button :loading="loading" @click="load">刷新</el-button></div><el-table :data="rows" v-loading="loading" empty-text="暂无员工"><el-table-column prop="userName" label="账号"/><el-table-column prop="nickName" label="姓名"/><el-table-column prop="phonenumber" label="手机号"/><el-table-column prop="deptName" label="部门"/><el-table-column label="状态"><template #default="s">{{s.row.status==='0'?'正常':'停用'}}</template></el-table-column></el-table></div></template>
<script setup>import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{getXyStaff}from'@/api/xy';const router=useRouter(),rows=ref([]),loading=ref(false);async function load(){loading.value=true;try{rows.value=await getXyStaff()}finally{loading.value=false}}onMounted(load)</script><style scoped>.page{padding:20px;background:#fff;border-radius:16px}.page>p{color:#6a7d79}.actions{display:flex;gap:10px;margin-bottom:16px}</style>
